		if doc.ID == "" {
			doc.ID = strings.TrimSuffix(f.Name, ".json")
		}
		runners = append(runners, tuneRunner{
			ID:       doc.ID,
			Name:     runnersName + "/" + f.Name,
			Path:     path,
